/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs`
        (`table_name`, `operation`, `db_users`, `description`)
    VALUES (
        'tb_people',
        'Create',
        USER(),
        CONCAT(
            'Datos personales creados. ID=', NEW.person_ID,
            ', user_ID=', NEW.user_ID,
            ', nombre=', NEW.given_names,
            ', apellidos=', COALESCE(NEW.family_names, 'NULL')
        )
    );
END */;;
