/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_refunds_validate_insert` BEFORE INSERT ON `tb_refunds` FOR EACH ROW BEGIN
  IF NEW.`return_ID` IS NULL AND NEW.`cancellation_ID` IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El reembolso debe asociarse a una devolución o cancelación';
  END IF;
END */;;
