CREATE DEFINER=`root`@`localhost` FUNCTION `fn_random_account_status`(
    p_active_probability DECIMAL(5,4)
) RETURNS tinyint unsigned
    NO SQL
BEGIN
    IF p_active_probability IS NULL
       OR p_active_probability < 0
       OR p_active_probability > 1 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La probabilidad activa debe estar entre 0 y 1';
    END IF;

    RETURN IF(RAND() < p_active_probability, 1, 0);
END ;;
