CREATE DEFINER=`root`@`localhost` FUNCTION `fn_random_birth_date`(
    p_min_age SMALLINT UNSIGNED,
    p_max_age SMALLINT UNSIGNED
) RETURNS date
    NO SQL
BEGIN
    DECLARE v_min_age SMALLINT UNSIGNED;
    DECLARE v_max_age SMALLINT UNSIGNED;
    DECLARE v_first_date DATE;
    DECLARE v_last_date DATE;
    DECLARE v_days INT UNSIGNED;

    SET v_min_age = COALESCE(p_min_age, 18);
    SET v_max_age = COALESCE(p_max_age, 80);

    IF v_min_age > v_max_age OR v_max_age > 120 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Rango de edad invalido (min <= max <= 120)';
    END IF;

    SET v_first_date = DATE_SUB(CURDATE(), INTERVAL v_max_age YEAR);
    SET v_last_date = DATE_SUB(CURDATE(), INTERVAL v_min_age YEAR);
    SET v_days = DATEDIFF(v_last_date, v_first_date);

    RETURN DATE_ADD(v_first_date, INTERVAL FLOOR(RAND() * (v_days + 1)) DAY);
END ;;
DELIMITER ;
