CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_deactivate_user`(
    IN p_user_id INT UNSIGNED
)
BEGIN

    IF NOT EXISTS (
        SELECT 1
        FROM tb_users
        WHERE ID = p_user_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El usuario especificado no existe';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM tb_users
        WHERE ID = p_user_id
          AND status = b'0'
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El usuario ya se encuentra inactivo';
    END IF;

    UPDATE tb_users
    SET status = b'0'
    WHERE ID = p_user_id;

END ;;
DELIMITER ;
