CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_log_daily_metrics`()
    MODIFIES SQL DATA
BEGIN
    DECLARE v_user_count BIGINT UNSIGNED;
    DECLARE v_active_user_count BIGINT UNSIGNED;
    DECLARE v_product_count BIGINT UNSIGNED;

    SELECT COUNT(*) INTO v_user_count FROM tb_users;
    SELECT COUNT(*) INTO v_active_user_count
      FROM tb_users WHERE status = b'1';
    SELECT COUNT(*) INTO v_product_count FROM tb_products;

    INSERT INTO tb_logs (table_name, operation, db_users, description)
    VALUES (
        'system_metrics', 'Read', CURRENT_USER(),
        CONCAT('Resumen diario: usuarios=', v_user_count,
               ', usuarios_activos=', v_active_user_count,
               ', productos=', v_product_count)
    );
END ;;
DELIMITER ;
