DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_user`(
    IN p_email VARCHAR(80),
    IN p_nickname VARCHAR(100),
    IN p_password VARCHAR(255),

    IN p_title VARCHAR(30),
    IN p_given_names VARCHAR(150),
    IN p_family_names VARCHAR(150),
    IN p_birth_date DATE,
    IN p_gender_ID TINYINT UNSIGNED,
    IN p_phone VARCHAR(25),
    IN p_country_code CHAR(2)
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_user_ID INT UNSIGNED;
    DECLARE v_person_ID BIGINT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- 1. Crear la cuenta de usuario
    INSERT INTO `tb_users` (
        `email`,
        `nickname`,
        `password`,
        `status`
    )
    VALUES (
        p_email,
        p_nickname,
        p_password,
        b'1'
    );

    SET v_user_ID = LAST_INSERT_ID();

    -- 2. Crear los datos personales relacionados
    INSERT INTO `tb_people` (
        `user_ID`,
        `title`,
        `given_names`,
        `family_names`,
        `birth_date`,
        `gender_ID`,
        `phone`,
        `country_code`,
        `status`
    )
    VALUES (
        v_user_ID,
        p_title,
        p_given_names,
        p_family_names,
        p_birth_date,
        p_gender_ID,
        p_phone,
        p_country_code,
        b'1'
    );

    SET v_person_ID = LAST_INSERT_ID();

    COMMIT;

    -- 3. Devolver los identificadores creados
    SELECT
        v_user_ID AS user_ID,
        v_person_ID AS person_ID,
        'Usuario registrado correctamente' AS mensaje;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
