/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_simulate_users`(
    IN p_num_users INT UNSIGNED,
    IN p_gender_id TINYINT UNSIGNED,
    IN p_country_code CHAR(2),
    IN p_min_age SMALLINT UNSIGNED,
    IN p_max_age SMALLINT UNSIGNED,
    IN p_active_probability DECIMAL(5,4),
    OUT p_first_user_id INT UNSIGNED,
    OUT p_last_user_id INT UNSIGNED
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_min_age SMALLINT UNSIGNED;
    DECLARE v_max_age SMALLINT UNSIGNED;
    DECLARE v_country CHAR(2);
    DECLARE v_uuid CHAR(32);
    DECLARE v_suffix CHAR(8);
    DECLARE v_given_name VARCHAR(40);
    DECLARE v_family_names VARCHAR(80);
    DECLARE v_email_domain VARCHAR(30);
    DECLARE v_email VARCHAR(80);
    DECLARE v_nickname VARCHAR(100);
    DECLARE v_password_hash CHAR(64);
    DECLARE v_user_id INT UNSIGNED;
    DECLARE v_user_status TINYINT UNSIGNED;
    DECLARE v_birth_date DATE;
    DECLARE v_i INT UNSIGNED DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SET p_first_user_id = NULL;
    SET p_last_user_id = NULL;

    IF p_num_users IS NULL OR p_num_users < 1 OR p_num_users > 5000 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'p_num_users debe estar entre 1 y 5000';
    END IF;

    IF p_active_probability IS NULL
       OR p_active_probability < 0
       OR p_active_probability > 1 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La probabilidad activa debe estar entre 0 y 1';
    END IF;

    SET v_min_age = COALESCE(p_min_age, 18);
    SET v_max_age = COALESCE(p_max_age, 80);

    IF v_min_age > v_max_age OR v_max_age > 120 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Rango de edad invalido (min <= max <= 120)';
    END IF;

    IF p_country_code IS NOT NULL
       AND TRIM(p_country_code) <> '*'
       AND CHAR_LENGTH(TRIM(p_country_code)) <> 2 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'p_country_code debe ser ISO alfa-2, NULL o *';
    END IF;

    START TRANSACTION;

    WHILE v_i < p_num_users DO
        SET v_uuid = REPLACE(UUID(), '-', '');
        SET v_suffix = LPAD(FLOOR(RAND() * 100000000), 8, '0');
        SET v_given_name = fn_random_given_name(p_gender_id);
        SET v_family_names = CONCAT(fn_random_family_name(), ' ', fn_random_family_name());
        SET v_email_domain = fn_random_email_domain();
        SET v_email = CONCAT(
            LOWER(v_given_name), '.',
            LOWER(SUBSTRING_INDEX(v_family_names, ' ', 1)),
            v_suffix, '@', v_email_domain
        );
        SET v_nickname = CONCAT(
            LOWER(v_given_name), '.',
            LOWER(SUBSTRING_INDEX(v_family_names, ' ', 1)),
            v_suffix
        );
        SET v_password_hash = SHA2(CONCAT(v_uuid, UUID()), 256);
        SET v_user_status = fn_random_account_status(p_active_probability);
        SET v_birth_date = fn_random_birth_date(v_min_age, v_max_age);

        IF p_country_code IS NULL OR TRIM(p_country_code) = '*' THEN
            SET v_country = fn_random_country_code();
        ELSE
            SET v_country = UPPER(TRIM(p_country_code));
        END IF;

        INSERT INTO tb_users (email, nickname, password, status)
        VALUES (v_email, v_nickname, v_password_hash, v_user_status);

        SET v_user_id = LAST_INSERT_ID();
        IF v_i = 0 THEN
            SET p_first_user_id = v_user_id;
        END IF;
        SET p_last_user_id = v_user_id;

        INSERT INTO tb_people (
            user_ID, title, given_names, family_names, birth_date,
            gender_ID, phone, country_code, status
        )
        VALUES (
            v_user_id, NULL, v_given_name, v_family_names, v_birth_date,
            p_gender_id, NULL, v_country, b'1'
        );

        SET v_i = v_i + 1;
    END WHILE;

    COMMIT;

    SELECT p_num_users AS inserted_users,
           p_first_user_id AS first_user_id,
           p_last_user_id AS last_user_id,
           v_min_age AS min_age,
           v_max_age AS max_age,
           p_active_probability AS active_probability;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
