,`categorized_products`.`product_ID` AS `product_ID`,`categorized_products`.`SKU` AS `SKU`,`categorized_products`.`product_name` AS `product_name`,`categorized_products`.`current_stock` AS `current_stock`,`categorized_products`.`availability_status` AS `availability_status`,`categorized_products`.`availability_label` AS `availability_label` from `categorized_products` union all select NULL AS `category_ID`,'Sin categoría' AS `category_name`,'Productos sin categoría' AS `category_path`,NULL AS `category_level`,`uncategorized_products`.`product_ID` AS `product_ID`,`uncategorized_products`.`SKU` AS `SKU`,`uncategorized_products`.`product_name` AS `product_name`,`uncategorized_products`.`current_stock` AS `current_stock`,`uncategorized_products`.`availability_status` AS `availability_status`,`uncategorized_products`.`availability_label` AS `availability_label` from `uncategorized_products` */;
